from taf.cloud.lcmaas.schemas.schema_base import SchemaObject, SchemaField


class ImageRegistry(SchemaObject):
    addr = SchemaField(name='addr')
    ca_certs = SchemaField(name='ca_certs')
    password = SchemaField(name='password')
    user = SchemaField(name='user')

    def __init__(self, addr, ca_certs, password, user):
        self.addr = addr
        self.ca_certs = ca_certs
        self.password = password
        self.user = user

        super(ImageRegistry, self).__init__()


class VIInfoV1(SchemaObject):
    name = SchemaField(name="name", not_null=True)
    status = SchemaField(name="status", not_null=True)
    kube_config = SchemaField(name="kube_config", not_null=True)
    image_registry = SchemaField(name="image_registry", klass=ImageRegistry, not_null=True)
    neat = SchemaField(name="neat", optional=True)

    def __init__(self, name, status, kube_config, image_registry, neat):
        self.name = name
        self.status = status
        self.kube_config = kube_config
        self.image_registry = image_registry
        self.neat = neat
        super(VIInfoV1, self).__init__()
